    if(kind==='schedule'){const cycle=d.cycle[s.cycle||'retro'],cadence=Number(v.get('cadence')),zone=String(v.get('timezone'));if(!cycle||!Number.isInteger(cadence)||cadence<5||cadence>1440||!['Europe/Warsaw','UTC'].includes(zone)){wbScheduleUi(d).error='Нужен интервал 5–1440 минут и известная временная зона.';rerender();return}cycle.cadence=String(cadence);cycle.timezone=zone;cycle.revision=(cycle.revision||1)+1;wbScheduleUi(d).error=''}
