    if(a==='apply-manager'&&mg.phase==='checkpoint'){mg.phase='waiting';mg.revision++;mg.provider=mg.candidate}
    if(a==='manager-ack'&&mg.phase==='waiting')mg.phase='acknowledged'
    if(a==='cycle-ready'){cycle.bindingReady=true;cycle.phase='ready'}
    if(a==='cycle-next-window'&&!['admitted','inflight','unknown'].includes(cycle.phase)){cycle.windowIndex=(cycle.windowIndex||0)+1;cycle.manualWindow=null;cycle.coalesced=false;cycle.phase='ready'}
    if(a==='cycle-pause')cycle.paused=true;if(a==='cycle-resume'){const p=fixtures.projects.find(p=>p.id===s.project);if(['dormant','archived','purged'].includes(p?.lifecycle)||cycle.bindingReady===false||!wbScheduleMayWrite(s,d)){cycle.phase='unready'}else cycle.paused=false}
    const tick=(status,result)=>{cycle.ticks.push({id:'tick-'+(s.cycle||'retro')+'-'+(cycle.ticks.length+1),status,result,window:'window-'+(cycle.windowIndex||0),revision:routineStore(s.project).records.find(r=>r.id===cycle.routineId)?.revision,provider:routineStore(s.project).records.find(r=>r.id===cycle.routineId)?.provider});cycle.phase='ready'}
